import{z as o,x as s,o as l,c as p,q as r,j as t,D as A,d as a,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"在线偏好更新","description":"","frontmatter":{"title":"在线偏好更新","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-online-preference.md","filePath":"llm/continual-online-preference.md","lastUpdated":1791413859000}'),d={name:"llm/continual-online-preference.md"};function D(m,E,f,c,P,h){const B=s("Mermaid");return l(),p("div",null,[E[2]||(E[2]=r('<h1 id="在线偏好更新" tabindex="-1">在线偏好更新 <a class="header-anchor" href="#在线偏好更新" aria-label="Permalink to &quot;在线偏好更新&quot;">​</a></h1><div class="epigraph"><p>偏好是一股流，不是一个数据集；批量对齐每跑一轮，模型就在旧世界上多待了一个周期。</p><footer>—— 据 Rafailov 等 2023（DPO）与迭代式在线 DPO 实践整理</footer></div><p><a href="/llm/continual-model-merge">上一课</a>把阶段性能力固化成部署物，节奏是按月；用户偏变的节奏是按天。本课把更新节奏压到流式：模型在服务中持续产生候选回答，反馈持续回来，权重持续小步更新。主干<a href="/llm/iterative-online-dpo">迭代与在线 DPO</a>已写过参考策略跟不跟的取舍，本课把整条在线环当作一个持续学习装置来看：它的稳定条件、它放大的风险、以及它和前几课机制的关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>批量 RLHF 的流程是攒几个月的数据、训一版奖励模型、跑一轮 PPO、发布。偏好在这几个月里早就移动了：新功能上线改变用户行为，季节改变语气期望。在线更新解决的正是时滞，但引入三个新问题。标签过时：旧策略的回答对新策略是离 policy 的，更新越频，历史对的价值衰减越快。标签来源：在线环里人工标注跟不上，用模型或奖励模型打标，标注器的偏置进入环里被放大。稳定性：小步高频更新没有批量流程的验收缓冲，一次坏更新直接触达用户。</p><p><span class="marginnote">DPO 的损失只依赖策略与参考的对数几率差，省掉了显式奖励模型与采样强化学习两个组件，这是它能塞进在线环的工程前提；PPO 环在线化的成本结构见 PPO 在语言模型中的实现一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环的骨架五步：当前策略对同一提示采样两个回答；由标注通道给出偏好（人工、奖励模型或强模型仲裁）；按 DPO 目标更新一步；灰度验证后替换线上；流量数据回流。三个稳定器必须一起上。回放：每批混入历史偏好对——上一课合并是权重的回放，这里是偏好的回放——防止策略在最近几天的偏移上过冲，参照<a href="/llm/continual-replay-buffer">回放缓冲与经验回放</a>的配比逻辑。KL 锚：对参考策略的正则相当于概率空间里的 EWC，把每步更新限制在「没有新证据支撑的方向」之外，\\(\\beta\\) 是它的旋钮。验收门：每次发布前过一遍冻结探针与新偏好胜率，频率可以高，门不能省。</p><p><span class="marginnote">KL 锚可以想象成一根拴在参考策略上的橡皮筋：每一步更新都往新偏好的方向拉，橡皮筋则往回拽。拽力调太松（\\(\\beta\\) 太小），模型一天变个样；拽太紧（\\(\\beta\\) 太大），新偏好永远学不进来。\\(\\beta\\) 就是调这根橡皮筋松紧的旋钮。</span></p>',9)),(l(),t(i,null,{default:A(()=>[n(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SERVE%5B%22%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E6%9C%8D%E5%8A%A1%E6%B5%81%E9%87%8F%22%5D%20--%3E%20SAMP%5B%22%E5%90%8C%E6%8F%90%E7%A4%BA%E9%87%87%E4%B8%A4%E4%B8%AA%E5%9B%9E%E7%AD%94%22%5D%0A%20%20SAMP%20--%3E%20LABEL%5B%22%E6%A0%87%E6%B3%A8%E9%80%9A%E9%81%93%EF%BC%9A%E4%BA%BA%E5%B7%A5%2F%E5%A5%96%E5%8A%B1%E6%A8%A1%E5%9E%8B%2F%E4%BB%B2%E8%A3%81%22%5D%0A%20%20LABEL%20--%3E%20UPD%5B%22DPO%20%E5%B0%8F%E6%AD%A5%E6%9B%B4%E6%96%B0%EF%BC%88%E6%B7%B7%E5%85%A5%E5%8E%86%E5%8F%B2%E5%81%8F%E5%A5%BD%E5%AF%B9%EF%BC%89%22%5D%0A%20%20UPD%20--%3E%20GATE%7B%22%E6%8E%A2%E9%92%88%E9%80%9A%E8%BF%87%E4%B8%94%E5%81%8F%E5%A5%BD%E8%83%9C%E7%8E%87%E8%BE%BE%E6%A0%87%3F%22%7D%0A%20%20GATE%20--%3E%7C%E5%90%A6%7C%20ROLL%5B%22%E5%9B%9E%E6%BB%9A%E6%9C%AC%E6%AD%A5%22%5D%0A%20%20GATE%20--%3E%7C%E6%98%AF%7C%20SHIP%5B%22%E7%81%B0%E5%BA%A6%E6%9B%BF%E6%8D%A2%E7%BA%BF%E4%B8%8A%22%5D%0A%20%20SHIP%20--%3E%20SERVE%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("在线环的真正风险是自指：策略产出回答，回答变成训练数据，策略再产出回答。环闭合后，任何系统性偏置都会按圈放大。最常见的两类：策略学会讨好标注器而非说对话——"),e("a",{href:"/llm/reward-hacking-llm"},"奖励黑客"),a("的在线版，症状是语气越来越谄媚而事实密度下降；标注器自身偏置被吸收，模型与奖励模型互相强化，"),e("a",{href:"/llm/self-preference-bias"},"自我偏好"),a("描述的正是这个回路的温床。对策都在环外：抽样审计真实人工标签、监控事实性与长度的边际指标、定期换参考策略重置漂移。")],-1)),E[5]||(E[5]=e("p",null,"这个自指环为什么必然放大偏置，值得单独画出来看：",-1)),(l(),t(i,null,{default:A(()=>[n(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%22%5D%20--%3E%20B%5B%22%E7%94%A8%E5%AE%83%E7%94%9F%E6%88%90%E5%9B%9E%E7%AD%94%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%A0%87%E6%B3%A8%E5%99%A8%E6%8C%89%E8%87%AA%E5%B7%B1%E7%9A%84%E5%8F%A3%E5%91%B3%E6%8C%91%E6%9B%B4%E5%A5%BD%E7%9A%84%E9%82%A3%E4%B8%AA%22%5D%0A%20%20C%20--%3E%20D%5B%22DPO%20%E6%9B%B4%E6%96%B0%E6%9D%83%E9%87%8D%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%AD%96%E7%95%A5%E5%90%91%E6%A0%87%E6%B3%A8%E5%99%A8%E5%8F%A3%E5%91%B3%E9%9D%A0%E6%8B%A2%E4%B8%80%E6%AD%A5%22%5D%0A%20%20E%20--%3E%20B%0A%20%20E%20-.%20%22%E6%AF%8F%E8%BD%AC%E4%B8%80%E5%9C%88%2C%E5%81%8F%E7%BD%AE%E4%B9%98%E4%B8%80%E6%AC%A1%E7%B3%BB%E6%95%B0%22%20.-%3E%20F%5B%22%E7%8E%AF%E5%A4%96%E9%97%B8%E9%97%A8%3A%E4%BA%BA%E5%B7%A5%E5%AE%A1%E8%AE%A1%20%2B%20%E4%BA%8B%E5%AE%9E%E5%AF%86%E5%BA%A6%E7%9B%91%E6%8E%A7%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p>离 policy 标签为什么必须丢：偏好对的标签绑定产生它的策略。策略移动之后，旧对回答的是「旧策略的哪个回答更好」，对当前策略的梯度是带偏差的估计。这与<a href="/llm/contextual-bandits">上下文 bandit</a>的过期日志偏差同构：数据的价值半衰期由策略更新速率决定，两者必须配速。把「更新多快」与「标签多快过期」放进同一预算，是在线偏好更新的核心纪律。</p><p><span class="marginnote">「离 policy」翻译过来就是「数据是别的版本的你产出的」。好比拿去年的你写的日记训练今天的你：日记里的选择反映的是去年的口味，照单全收，学到的可能是早该丢掉的旧习惯——所以旧偏好对要么按比例混入（回放），要么按期丢弃。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>在线环不适合一切偏好信号。隐式反馈——点选、停留、复制——噪声大且混杂展示偏置，直接进环会训出流量的奴隶，<a href="/llm/implicit-feedback-prefs">隐式反馈：点选与停留</a>的清洗结论要先落地。边界收敛快的域，用批量流程更便宜也更稳；在线的溢价只在偏变快、反馈真、量够大的场景兑现。隐私与合规在环里无处可藏：用户提示进入训练数据是处理个人数据，入库前的脱敏与同意分级是硬约束，本课程后面有专课。最后，评测协议必须跟着流式化——静态评测集会被环里的模型慢慢背下来，那是下一单元的主题。</p><p><span class="marginnote">常见误区：以为一套评测集可以用到底。在线模型每天大量生成文本，同一批题反复出现，等于把期末卷发给考生天天刷——分数涨了、能力没涨。流式更新必须配滚动换题的流式评测。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>在线偏好更新把批量 RLHF 的周期压缩成流：采样、标注、小步更新、灰度、回流。</li><li>三个稳定器缺一不可：偏好对的回放、对参考策略的 KL 锚、高频但不缺席的验收门。</li><li>标签价值随策略更新衰减，配速纪律是把更新速率与标签半衰期放进同一预算。</li><li>闭环自指放大一切偏置：奖励黑客与自我偏好要在环外用人工审计与边际指标拦。</li><li>隐式反馈先清洗再进环；在线的溢价只在偏变快、反馈真的场景兑现。</li><li>出处：Rafailov 等 2023（DPO）；迭代式在线 DPO 的公开工程实践；Sutton 与 Barto 2018 对在线学习-行动耦合的一般讨论。</li></ul>',7))])}const C=o(d,[["render",D]]);export{F as __pageData,C as default};
